<?php
declare(strict_types=1);
$root=sys_get_temp_dir().DIRECTORY_SEPARATOR.'kalite-filo-unsubscribe-'.bin2hex(random_bytes(6));$path=$root.DIRECTORY_SEPARATOR.'newsletter-contacts.csv';putenv('KALITE_FILO_CONTACT_STORE_PATH='.$path);require_once dirname(__DIR__).'/unsubscribe-store.php';require_once dirname(__DIR__).'/export-iys-daily.php';
function unsubscribe_test_assert(bool $condition,string $message):void{if(!$condition)throw new RuntimeException($message);}function unsubscribe_test_remove(string $path):void{if(!is_dir($path))return;foreach(scandir($path)?:[] as $entry){if($entry==='.'||$entry==='..')continue;$item=$path.DIRECTORY_SEPARATOR.$entry;is_dir($item)?unsubscribe_test_remove($item):@unlink($item);}@rmdir($path);}
try{kalite_filo_store_commercial_email_consent('person@example.com','website_newsletter');$token=kalite_filo_issue_unsubscribe_token('person@example.com');unsubscribe_test_assert(preg_match('/^[a-f0-9]{64}$/',$token)===1,'Opaque token must contain 256 random bits.');$stored=(string)file_get_contents(kalite_filo_unsubscribe_token_store_path());unsubscribe_test_assert(!str_contains($stored,$token)&&str_contains($stored,hash('sha256',$token)),'Raw unsubscribe token must never be stored.');unsubscribe_test_assert(kalite_filo_consume_unsubscribe_token($token),'Valid token must suppress the contact.');$rows=kalite_filo_read_contact_rows($path);unsubscribe_test_assert($rows[0]['status']==='unsubscribed'&&$rows[0]['unsubscribed_at']!=='','Suppression must preserve the row and set unsubscribe evidence.');unsubscribe_test_assert(kalite_filo_consume_unsubscribe_token($token),'Repeated token use must be idempotent.');unsubscribe_test_assert(!kalite_filo_consume_unsubscribe_token(str_repeat('a',64)),'Unknown token must fail closed.');}finally{unsubscribe_test_remove($root);}fwrite(STDOUT,"Unsubscribe store tests passed.\n");
